<?php
require_once __DIR__.'/../includes/auth.php';$admin=require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($id===(int)$admin['id']){flash('error','You cannot block your own admin account.');}elseif(in_array($action,['block','unblock'],true)){$st=$action==='block'?'blocked':'active';$q=db()->prepare("UPDATE users SET status=?,session_version=session_version+1 WHERE id=? AND role<>'admin'");$q->execute([$st,$id]);log_activity((int)$admin['id'],'user_'.$action,'user',$id);flash('success','User status updated.');}redirect('admin/users.php');}
$role=$_GET['role']??'';$pg=pagination_window(30,60);$sql='SELECT id,name,email,phone,role,status,city,state,created_at FROM users';$par=[];if(in_array($role,['customer','provider','business','admin'],true)){$sql.=' WHERE role=?';$par[]=$role;}$sql.=' ORDER BY id DESC LIMIT '.($pg['per']+1).' OFFSET '.$pg['offset'];$q=db()->prepare($sql);$q->execute($par);$rows=$q->fetchAll();$hasNext=trim_page_results($rows,$pg['per']);$success=flash('success');$error=flash('error');release_session_lock();$pageTitle='Manage Users — LocalConnect';require __DIR__.'/../includes/header.php';?>
<div class="container py-4"><?php include __DIR__.'/_nav.php';?><div class="d-flex justify-content-between align-items-center"><h1>Manage users</h1><form method="get"><select class="form-select" name="role" data-auto-submit><option value="">All roles</option><?php foreach(['customer','provider','business','admin'] as $r):?><option value="<?=$r?>" <?=$role===$r?'selected':''?>><?=e(role_label($r))?></option><?php endforeach;?></select></form></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="table-responsive card shadow-sm border-0"><table class="table mb-0"><tr><th>Name</th><th>Role</th><th>Status</th><th>Location</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e(role_label($r['role']))?></td><td><span class="badge text-bg-<?=$r['status']==='blocked'?'danger':'success'?>"><?=e($r['status'])?></span></td><td><?=e(trim(($r['city']??'').' '.($r['state']??'')))?></td><td><?php if($r['role']!=='admin'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="<?=$r['status']==='blocked'?'unblock':'block'?>"><button class="btn btn-sm btn-outline-<?=$r['status']==='blocked'?'success':'danger'?>"><?=$r['status']==='blocked'?'Unblock':'Block'?></button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?=pagination_nav($pg['page'],$hasNext)?></div><?php require __DIR__.'/../includes/footer.php';?>
